<template>
		
<FormulateForm
	v-if="!loading"
	ref="form"
	v-model="form"
	@submit="save" 
	>
	
	<FormulateInput
		label="CJP"
		name="cjp"
		validation-name="CJP"
		validation="required"
	/>

	<FormulateInput
		label="Nombre"
		name="name"
		validation-name="Nombre"
		validation="required"
	/>
	
	<FormulateInput
		label="Apellido"
		name="lastname"
		validation-name="Apellido"
		validation="required"
	/>

	<FormulateInput
		type="identification"
		label="Documento de identidad"
		name="document"
		validation-name="Documento de identidad"
		validation="optional|^documentID"
	/>


	<FormulateInput
		class="mt-2"
		type="date"
		name="birthdate"
		validation-name="La fecha de nacimiento"
		label="Fecha de nacimiento"
		:splitted="true"
		:validation="`required|isAdult`"
		help="Edad mínima 18 años"
	/>



	<FormulateInput
		label="Email"
		type="email"
		name="email"
		validation-name="Email"
		validation="required"
	/>

	<FormulateInput
		label="Teléfono"
		type="phone"
		name="phone"
		validation-name="Teléfono"
		validation="optional|^phone"
	/>
	
	<div class="section-title mt-4 mb-2">Dirección de residencia</div>
	<div class="row row-xs">
		<div class="col-12 col-md-6 mb-2">
			<FormulateInput
				label="País"
				validation-name="País"
				name="addressCountry"
				:options="countries"
				type="selectSearch"
				option-value="id"
				option-text="name"
				placeholder="Seleccione un país"
				validation="required"
				:disabled="loadingCountries"
			/>
			<div class="formulate-input-help " v-if="loadingCountries">Cargando paises...</div>
		</div>
		<div class="col-12 col-md-6 mb-2">
			<FormulateInput
				label="Ciudad"
				name="addressCity"
				validation-name="Ciudad"
				validation="required"
			/>
		</div>
	</div>

	<FormulateInput
		label="Calle número, etc..."
		name="addressStreet"
		validation-name="Ciudad"
		validation="required"
		help="Dirección (calle, número, apartamento, etc...)"
	/>
	
	<div class="d-flex justify-content-between mt-4">
		<FormulateInput type="button" data-ghost @click="$router.go(-1)" >Cancelar</FormulateInput>
		<FormulateInput type="button" disabled v-if="saving">Guardando <span class="loader" /></FormulateInput>
		<FormulateInput type="submit" :label="title" v-else />
	</div>

</FormulateForm>

</template>

<script>
import gql from 'graphql-tag'
import mixins from '@/mixins/mixins'
import formMixins from '@/mixins/formMixins'

export default {
	name: 'ClientForm',
	mixins: [mixins, formMixins],
	props:{
		id:{
			required:true
		}
	},
	data () {
		return {
			title: 'Crear médico',
			action: 'create',
			loading: true,
			saving: false,
			loadingCountries: true,
			countries: [],
			form:{
				cjp: null,
				name: null,
				lastname: null,
				document:{
					type: 'UY', number: null
				},
				birthdate: null,
				email: null,
				phone: null,
				address: { country: null, city: null, street:null},
			},
		}
	},

	async beforeMount(){
		await this.fetchData()
		if(this.id){
			this.action = 'update'
			this.title = `Editar médico`
			await this.load()
		}
		this.loading = false
	},
	methods:{
		save(){
			if(!this.saving){
				this.saving = true
				let dataInput = {
					cjp: this.form.cjp,
					name: this.form.name,
					lastname: this.form.lastname,
					email: this.form.email,
					document: this.form.document,
					birthdate: this.$moment(this.form.birthdate).format('YYYY-MM-DD'),
					phone: this.form.phone,
					addressCountry: this.form.addressCountry,
					addressCity: this.form.addressCity,
					addressStreet: this.form.addressStreet,
				}
				
				if(this.action =='create'){
					this.create(dataInput)
				}
				if(this.action =='update'){
					this.update(dataInput)
				}
			}
		},


		create(data){
			this.$apollo.mutate({
				mutation: gql`mutation ( $data:MedicInput! ){
					medicCreate( data: $data) {
						id
						name
						email
					}
				}`,
				variables: {
					data
				}
			})
			.then(({data}) => {
				this.$toast.success('Médico creado correctamente')
				this.$emit('created', data.medicCreate)
				this.saving = false
			})
			.catch( (error) => {
				this.parseGQLErrors(error)
				this.saving = false
			})
		},

		
		update(dataInput){
			this.$apollo.mutate({
				mutation: gql`mutation ( $id: ID!, $data:MedicInput! ){
					medicUpdate( id: $id, data: $data) {
						id
						name
						email
					}
				}`,
				variables: {
					id: this.id,
					data: dataInput
				}
			})
			.then(({data}) => {
				this.$toast.success('Médico editado correctamente')
				this.$emit('updated', data.medicUpdate)
				this.saving = false
			})
			.catch( (error) => {
				this.errors = this.parseGQLErrors(error)
				this.saving = false
			})
		},

		load(){
			return this.$apollo.query({
				query: gql`query ($id: ID!) {
					medic(id: $id) {
						id
						cjp
						name
						lastname
						email
						birthdate
						document{
							type
							number
						}
						phone{
							countryCode
							national
							international
							type
							validated
						}
						address{
							country{id name} city street
						}
					}
				}`,
				variables: { id: this.id },
				fetchPolicy: 'network-only',
			})
			.then(({data}) => {		
				console.log(data)		
				this.form = {
					...this.$omitDeep(data.medic, "__typename"),
					addressCountry: (data.medic.address && data.medic.address.country ) ? data.medic.address.country.id : null,
					addressCity: (data.medic.address && data.medic.address.city ) ? data.medic.address.city : null,
					addressStreet: (data.medic.address && data.medic.address.street ) ? data.medic.address.street : null,
				}
			})
			.catch((err)=>{
				this.$toast.success('El item que desea editar no existe')
				// this.$router.go(-1)
			})
		},


		fetchData(){
			this.loadingCountries = true
			return this.$apollo.query({
				query: gql`query {
					countries {
						id
						iso
						name
						nativeName
						flag
					}
				}`,
				fetchPolicy: 'network-only',
			})
			.then(({data}) => {
				this.countries = data.countries
				this.loadingCountries = false
			})
			.catch((err)=>{
				console.log(err)
			})

		},
	
	}
}


</script>

